PROGRAM Conveyor

(* SFC Generated from Visual Editor *)

VAR
    (* Step Active Flags *)
    X_step_stopped : BOOL := TRUE; (* Step: STOPPED *)
    X_step_running : BOOL := FALSE; (* Step: RUNNING *)
    X_step_fault : BOOL := FALSE; (* Step: FAULT *)

    (* Step Elapsed Timers *)
    T_step_stopped : TON; (* Timer for STOPPED *)
    T_step_running : TON; (* Timer for RUNNING *)
    T_step_fault : TON; (* Timer for FAULT *)

    (* Transitions That Fire In This Scan *)
    _F_t_start : BOOL;
    _F_t_jam : BOOL;
    _F_t_stop : BOOL;
    _F_t_reset : BOOL;
    (* Transition Conditions, as They Were Evaluated In This Scan *)
    _C_t_start : BOOL;
    _C_t_jam : BOOL;
    _C_t_stop : BOOL;
    _C_t_reset : BOOL;

END_VAR

VAR
    MetalLatched : BOOL := FALSE; (* A metal part was seen and has not reached the diverter *)
END_VAR

VAR_INPUT
    Start AT %I0.0 : BOOL; (* Start pushbutton *)
    Stop AT %I0.1 : BOOL; (* Stop pushbutton *)
    Reset AT %I0.2 : BOOL; (* Fault reset *)
    PartAtClassifier AT %I0.3 : BOOL; (* Part at the classifier *)
    MetalDetected AT %I0.4 : BOOL; (* Metal seen at the classifier *)
    PartAtDiverter AT %I0.5 : BOOL; (* Part at the diverter *)
    JamDetected AT %I0.6 : BOOL; (* Jam sensor *)
END_VAR

VAR_OUTPUT
    BeltCommand AT %Q0.0 : BOOL; (* Belt motor *)
    DiverterCommand AT %Q0.1 : BOOL; (* Metal diverter *)
    FaultLamp AT %Q0.2 : BOOL; (* Fault lamp *)
END_VAR

(* === Step Timers === *)
T_step_stopped(IN := X_step_stopped, PT := T#24h);
T_step_running(IN := X_step_running, PT := T#24h);
T_step_fault(IN := X_step_fault, PT := T#24h);

(* === Action Execution === *)
(* Action: A_STOPPED *)
IF X_step_stopped THEN
    BeltCommand := FALSE; DiverterCommand := FALSE; FaultLamp := FALSE;
END_IF;

(* Action: A_RUN *)
IF X_step_running THEN
    BeltCommand := TRUE; FaultLamp := FALSE;
    IF PartAtClassifier AND MetalDetected THEN MetalLatched := TRUE; END_IF;
    DiverterCommand := PartAtDiverter AND MetalLatched;
    IF PartAtDiverter THEN MetalLatched := FALSE; END_IF;
END_IF;

(* Action: A_FAULT *)
IF X_step_fault THEN
    BeltCommand := FALSE; DiverterCommand := FALSE; FaultLamp := TRUE; MetalLatched := FALSE;
END_IF;

(* === Transition Logic === *)
(* Transition: STOPPED -> RUNNING *)
_C_t_start := (Start);
_F_t_start := X_step_stopped AND _C_t_start;
(* Transition: RUNNING -> FAULT (A jam wins over Stop) *)
_C_t_jam := (JamDetected);
_F_t_jam := X_step_running AND _C_t_jam;
(* Transition: RUNNING -> STOPPED *)
_C_t_stop := (Stop);
_F_t_stop := X_step_running AND _C_t_stop AND NOT _F_t_jam;
(* Transition: FAULT -> STOPPED (Reset works only once the jam is gone) *)
_C_t_reset := (Reset AND NOT JamDetected);
_F_t_reset := X_step_fault AND _C_t_reset;

IF _F_t_start THEN X_step_stopped := FALSE; END_IF;
IF _F_t_jam THEN X_step_running := FALSE; END_IF;
IF _F_t_stop THEN X_step_running := FALSE; END_IF;
IF _F_t_reset THEN X_step_fault := FALSE; END_IF;
IF _F_t_start THEN X_step_running := TRUE; END_IF;
IF _F_t_jam THEN X_step_fault := TRUE; END_IF;
IF _F_t_stop THEN X_step_stopped := TRUE; END_IF;
IF _F_t_reset THEN X_step_stopped := TRUE; END_IF;

END_PROGRAM

